sealed class UsageRampBar:FrameworkElement {
 public UsageRamp Ramp;public int Selected;public Action<double> SelectPoint;public Action<int,double> MovePoint;bool dragging;double pressX;
 public UsageRampBar(){Height=66;MinWidth=220;Focusable=true;Cursor=Cursors.Arrow;ToolTip="拖动圆点移动颜色位置；点击配色条空白处添加点。0%和100%端点固定。";
  MouseLeftButtonDown+=(s,e)=>{Focus();var p=e.GetPosition(this);int hit=PointAt(p.X,p.Y);if(hit>=0){Selected=hit;if(SelectPoint!=null)SelectPoint(Ramp.Stops[hit].Position);pressX=p.X;dragging=Ramp.Stops[hit].Position>0&&Ramp.Stops[hit].Position<100;if(dragging){CaptureMouse();Cursor=Cursors.SizeWE;}else Cursor=Cursors.Hand;}else if(p.Y>=7&&p.Y<=37&&SelectPoint!=null)SelectPoint(Percent(p.X));e.Handled=true;};
  MouseMove+=(s,e)=>{var p=e.GetPosition(this);if(dragging&&IsMouseCaptured&&e.LeftButton==MouseButtonState.Pressed){if(Math.Abs(p.X-pressX)>=2&&MovePoint!=null)MovePoint(Selected,Percent(p.X));}else Cursor=PointAt(p.X,p.Y)>=0?Cursors.Hand:Cursors.Arrow;};
  MouseLeftButtonUp+=(s,e)=>{if(dragging){dragging=false;ReleaseMouseCapture();Cursor=Cursors.Hand;e.Handled=true;}};LostMouseCapture+=(s,e)=>dragging=false;
  KeyDown+=(s,e)=>{if((e.Key==Key.Left||e.Key==Key.Right)&&MovePoint!=null&&Ramp!=null){MovePoint(Selected,Ramp.Stops[Selected].Position+(e.Key==Key.Left?-1:1));e.Handled=true;}};
 }
 double Percent(double x){return Math.Max(0,Math.Min(100,(x-6)/Math.Max(1,ActualWidth-12)*100));}
 public int PointAt(double x,double y){if(Ramp==null||y<0||y>53)return -1;int nearest=Enumerable.Range(0,Ramp.Stops.Count).OrderBy(i=>Math.Abs(6+(ActualWidth-12)*Ramp.Stops[i].Position/100-x)).First();return Math.Abs(6+(ActualWidth-12)*Ramp.Stops[nearest].Position/100-x)<=9?nearest:-1;}

 protected override void OnRender(DrawingContext dc){base.OnRender(dc);if(Ramp==null)return;double width=Math.Max(1,ActualWidth-12);var rect=new Rect(6,7,width,30);if(Ramp.Mode=="mosaic"){for(int i=0;i<Ramp.Cells;i++){var c=Ramp.At((i+.5)/Ramp.Cells*100);dc.DrawRoundedRectangle(new SolidColorBrush(Color.FromRgb(c.R,c.G,c.B)),null,new Rect(6+width*i/Ramp.Cells,7,Math.Max(.1,width/Ramp.Cells-1.5),30),2,2);}}else{var brush=new LinearGradientBrush();brush.StartPoint=new Point(0,0);brush.EndPoint=new Point(1,0);foreach(var stop in Ramp.Stops.OrderBy(s=>s.Position))brush.GradientStops.Add(new GradientStop((Color)ColorConverter.ConvertFromString(stop.Color),stop.Position/100));dc.DrawRoundedRectangle(brush,null,rect,5,5);}for(int i=0;i<Ramp.Stops.Count;i++){var stop=Ramp.Stops[i];double x=6+width*stop.Position/100;dc.DrawEllipse((Brush)new SolidColorBrush((Color)ColorConverter.ConvertFromString(stop.Color)),new Pen(i==Selected?Brushes.White:Brushes.SlateGray,i==Selected?3:1),new Point(x,43),6,6);}}
}
